<div class="row"><div><label>Name</label><input name="name" required maxlength="160" value="<?= e($i['name']) ?>" placeholder="e.g. PLA 1.75mm 1kg, Black"></div><div><label>SKU (optional)</label><input name="sku" maxlength="40" value="<?= e($i['sku']) ?>"></div></div>
<div class="row"><div><label>Category</label><select name="category"><?= options(STOCK_CATEGORIES, $i['category']) ?></select></div><div><label>Material</label><input name="material" maxlength="40" value="<?= e($i['material']) ?>"></div><div><label>Colour</label><input name="color" maxlength="40" value="<?= e($i['color']) ?>"></div></div>
<div class="row"><div><label>Unit (spool, kg, pcs…)</label><input name="unit" maxlength="20" value="<?= e($i['unit']) ?>"></div><div><label>Reorder when stock ≤</label><input name="reorder_level" inputmode="decimal" value="<?= e($i['reorder_level']) ?>"></div><div><label>Unit cost ₹ (optional)</label><input name="unit_cost" inputmode="decimal" value="<?= e($i['unit_cost']) ?>"></div></div>
<div class="row"><div><label>Location</label><input name="location" maxlength="80" value="<?= e($i['location']) ?>"></div><div><label>Supplier</label><input name="supplier" maxlength="120" value="<?= e($i['supplier']) ?>"></div></div>
<label>Notes</label><textarea name="notes" rows="3"><?= e($i['notes']) ?></textarea>
